#!/bin/bash
# usage: codex-delta-review.sh <pr> <tag> <base-sha> <prev-review-file|-> <effort> "<focus>"  ; waits CI, reviews base..head delta with Codex sol; prints 3 lines
PR=$1; TAG=$2; BASE=$3; PREV=$4; EFF=$5; FOCUS=$6; R=/c/Users/gumac/AI/shipde-platform; L=$R/.worktrees/logs/night
cd $R; for i in $(seq 1 15); do r=$(gh pr view $PR --json statusCheckRollup --jq '[.statusCheckRollup[]|(.conclusion//"")]|join(",")'); echo "$r" | grep -qE '(^|,)(,|$)' && { sleep 60; continue; }; break; done
git fetch -q origin; H=$(gh pr view $PR --json headRefOid --jq .headRefOid)
echo "CI #$PR ${H:0:8}: $(gh pr view $PR --json statusCheckRollup --jq '[.statusCheckRollup[]|select(.conclusion!="SUCCESS" and .conclusion!="SKIPPED")|.name+"="+(.conclusion//.status)]|join(",")')"
# Gate: a red CI is a CHANGES_REQUIRED by itself; do not spend reviewer tokens on it.
FAILED=$(gh pr view $PR --json statusCheckRollup --jq '[.statusCheckRollup[]|select(.conclusion=="FAILURE" or .conclusion=="CANCELLED" or .conclusion=="TIMED_OUT")|.name]|unique|join(", ")')
if [ -n "$FAILED" ]; then printf 'VERDICT: CHANGES_REQUIRED\nReviewed SHA: %s\n\n1. **P1 — CI failing:** %s. Reproduce locally with the same commands as CI, fix, and re-run them green before committing.\n' "$H" "$FAILED" > $L/review-$TAG.txt; echo "$TAG exit=0 tokens=0 VERDICT: CHANGES_REQUIRED (CI gate: $FAILED) | open P0/P1: 1"; exit 0; fi
OWN=$(for f in $(git diff --name-only $BASE $H); do [ "$(git rev-parse -q --verify $H:$f 2>/dev/null)" = "$(git rev-parse -q --verify origin/main:$f 2>/dev/null)" ] || echo "$f"; done); FROMMAIN=$(( $(git diff --name-only $BASE $H | wc -l) - $(echo "$OWN" | grep -c .) )); if [ -n "$OWN" ]; then git diff $BASE $H -- $OWN > $L/delta-$TAG.patch; else : > $L/delta-$TAG.patch; fi; echo "delta $TAG: $(echo "$OWN" | grep -c .) own files, $FROMMAIN identical-to-main files excluded, $(wc -c < $L/delta-$TAG.patch) bytes"
{ echo "You are the independent reviewer (fresh task) for PR #$PR. Do NOT run commands or read files; everything is below. One reply. Focus: $FOCUS. Check each open P0/P1 of the previous review is truly fixed in the delta (cite file:line) and list NEW P0/P1. Output: line 1 VERDICT: PASS or VERDICT: CHANGES_REQUIRED, line 2 Reviewed SHA: $H, then numbered findings. P2 alone does not block."; echo; [ "$PREV" != "-" ] && { echo "=== PREVIOUS REVIEW ==="; cat $L/$PREV; echo; }; echo "=== GITHUB CI (gh pr view statusCheckRollup, exact head $H) ==="; gh pr view $PR --json statusCheckRollup --jq ".statusCheckRollup[]|\"\(.name)=\(.conclusion//.status) commit=$H\""; echo "NOTE: $FROMMAIN changed files whose content at head is byte-identical to origin/main (brought in by merging main) are excluded; they are main code, not this PR. Review only the files below."; echo "=== DELTA $BASE -> $H ==="; cat $L/delta-$TAG.patch; } > $L/rvprompt-$TAG.txt
cd $L && if [ -n "$OC" ]; then D=$L/oc-$TAG; mkdir -p $D && cp rvprompt-$TAG.txt $D/prompt.md && (cd $D && timeout 1800 opencode run -m "$OC" "Follow prompt.md exactly. Do not use any tools. Output only the review." -f prompt.md < /dev/null 2>&1 | sed "s/[[0-9;]*m//g" | awk "/^VERDICT:/{f=1} f" > $L/review-$TAG.txt) > rvlog-$TAG.log 2>&1; elif [ -n "$R9" ]; then node C:/Users/gumac/AppData/Local/Temp/claude/C--Users-gumac-AI-shipde-platform/05678e41-bc79-413b-8623-3be22ddbfec2/scratchpad/r9.js $R9 rvprompt-$TAG.txt review-$TAG.txt > rvlog-$TAG.log 2>&1; else timeout 1800 codex exec --skip-git-repo-check -s read-only ${AR:+-c 'model_providers.ar={name="agentrouter",base_url="https://agentrouter.org/v1",env_key="AGENTROUTER_API_KEY",wire_api="responses"}' -c model_provider=ar} -m ${RVM:-gpt-6.1-sol} -c model_reasoning_effort=$EFF -o review-$TAG.txt - < rvprompt-$TAG.txt > rvlog-$TAG.log 2>&1; fi
echo "$TAG exit=$? tokens=$(grep -A1 'tokens used' rvlog-$TAG.log | tail -1) $(head -1 review-$TAG.txt) | open P0/P1: $(grep -E 'P0|P1' review-$TAG.txt | grep -viE 'closed|fixed' | wc -l)"
